def digest(data:bytes)->str:return "sha256:"+hashlib.sha256(data).hexdigest()
def canonical(v:object)->bytes:return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":")).encode()
def row_hash(row:dict)->str:return digest(canonical(row))
def git_bytes(path:str)->bytes:
 try:
  return subprocess.check_output(["git","show",f"{BASE_REVISION}:{path}"],cwd=ROOT)
 except subprocess.CalledProcessError as exc:
  fail("E_BASE_SOURCE", f"{BASE_REVISION}:{path}")
  raise exc
def git_blob(path:str)->str:
 try:
  return subprocess.check_output(["git","rev-parse",f"{BASE_REVISION}:{path}"],cwd=ROOT,text=True).strip()
 except subprocess.CalledProcessError as exc:
  fail("E_BASE_SOURCE", f"{BASE_REVISION}:{path}")
  raise exc
def parse_jsonl(path:str)->list[dict]:return [json.loads(x) for x in git_bytes(path).decode().splitlines() if x.strip()]
def receipt(path:str,marker:str,archive=False)->dict:
 obj=ARCHIVE_PREFIX+path if archive else path; data=git_bytes(obj); lines=data.decode("utf-8","replace").splitlines(); hits=[i for i,l in enumerate(lines,1) if marker in l]
 if len(hits)!=1: raise RuntimeError(f"marker not unique: {path} {marker} {hits}")
 n=hits[0]; line=lines[n-1]
 if archive:
  end=min(len(lines),n+11); span="\n".join(lines[n-1:end]).encode()
  return {"line_start":n,"line_end":end,"marker":marker,"line_text":line,"line_text_sha256":digest(line.encode()),"span_sha256":digest(span)}
 return {"path":path,"blob":git_blob(path),"sha256":digest(data),"line":n,"marker":marker,"line_text":line,"line_text_sha256":digest(line.encode())}
def static_matches(path:str,terms:list[str])->dict:
 data=git_bytes(path); lines=data.decode("utf-8","replace").splitlines(); hits=[{"line":n,"text":l,"text_sha256":digest(l.encode())} for n,l in enumerate(lines,1) if any(t and t in l for t in terms)]
 return {"path":path,"blob":git_blob(path),"bytes":len(data),"sha256":digest(data),"matched_lines":hits}
def approval()->dict:
 out={}; ids={"HELIX-HARNESS":"HDEC-HARNESS-L1-01","HELIX-OS":"HDEC-HELIXOS-L1-01","HELIX-Web":"HDEC-HELIXWEB-L1-01","HELIX-Web-OS":"HDEC-HELIXWEBOS-L1-01"}
 for product,path in L1.items():out[product]={"decision_id":ids[product],"result":"approve","l1_path":path,"approved_l1_sha256":digest(git_bytes(path)),"decision_record_anchor":receipt(APPROVAL_DECISION,APPROVAL_ROWS[product]),"l1_revision_matches_decision":True}
 return {"decision_record":{**receipt(APPROVAL_DECISION,"decision_status: approved"),"decision_record_id":"HDEC-CONCEPT-V4.1-AND-FOUR-L1-2026-09-17","decision_status":"approved","authority_effect_declared_by_record":"effective_when_this_record_is_admitted_to_main"},"human_decision_packet":receipt(APPROVAL_PACKET,"human_decision_record:"),"products":out}
def boundary_base():
 ap=approval()
 return {"product_boundary":{**receipt(BOUNDARY,"## 対象別の正規入口"),"interpretation":"approved four-product meaning is referenced from the fixed human decision; this research scaffold grants no authority","product_spans":{p:receipt(BOUNDARY,BOUNDARY_MARKERS[p]) for p in PRODUCTS},"approved_meaning_spans":{p:receipt(APPROVAL_DECISION,APPROVAL_MEANING[p]) for p in PRODUCTS}},"l1":{p:{"raw_document":receipt(path,L1_HEAD[p]),"raw_metadata":{"status":"draft","authority_status":"awaiting_parent_approval","status_anchor":receipt(path,"status: draft"),"authority_anchor":receipt(path,"authority_status: awaiting_parent_approval")},"semantic_anchor":receipt(path,L1_HEAD[p]),"effective_approval":ap["products"][p],"interpretation":"raw L1 metadata remains draft; effective approved decision is evidenced separately; this scaffold grants no authority"} for p,path in L1.items()}}
def wave_data(ids:set[str],paths:set[str]):
 files=[];edges=[]
 for n,path in WAVE_PATHS.items():
  try:data=git_bytes(path)
  except subprocess.CalledProcessError:continue
  files.append({"wave":n,"path":path,"blob":git_blob(path),"bytes":len(data),"sha256":digest(data)})
  for line_no,line in enumerate(data.decode("utf-8","replace").splitlines(),1):
   if not line.strip():continue
   try:row=json.loads(line)
   except json.JSONDecodeError:continue
   if row.get("asset_id") in ids or row.get("source_path") in paths:
    identity={"wave":n,"path":path,"line":line_no,"asset_id":row.get("asset_id"),"source_path":row.get("source_path"),"unit_candidate_id":row.get("unit_candidate_id"),"semantic_link_status":row.get("semantic_link_status")}
    edges.append({"edge_id":digest(canonical(identity)),**identity,"row":row})
 return files,edges

