def verify_category_invariants(record):
    classification = record.get("classification", {})
    category = classification.get("category")
    products = classification.get("candidate_products")
    basis = classification.get("candidate_product_basis")
    boundary_l1 = record.get("boundary_evidence", {}).get("l1", {})
    source_marker = record.get("source_exact", {}).get("semantic_anchor", {}).get("marker")
    if not isinstance(products, list) or not isinstance(basis, dict):
        fail("E_CLASSIFICATION", record.get("asset_id"))
    if category == "direct_product_basis" and len(products) != 1:
        fail("E_CLASSIFICATION", record.get("asset_id"))
    if category == "multi_product_conflict" and len(products) < 2:
        fail("E_CLASSIFICATION", record.get("asset_id"))
    if category == "insufficient_basis" and len(products) != 0:
        fail("E_CLASSIFICATION", record.get("asset_id"))
    if category not in {"direct_product_basis", "multi_product_conflict", "insufficient_basis"}:
        fail("E_CLASSIFICATION", record.get("asset_id"))
    if set(basis) != set(products):
        fail("E_CLASSIFICATION", record.get("asset_id"))
    for product in products:
        item = basis.get(product)
        l1 = boundary_l1.get(product)
        if not isinstance(item, dict) or not isinstance(l1, dict) or not isinstance(l1.get("semantic_anchor"), dict):
            fail("E_CLASSIFICATION", record.get("asset_id"))
        if item.get("source_marker") != source_marker:
            fail("E_CLASSIFICATION", record.get("asset_id"))
        if item.get("l1_marker") != l1["semantic_anchor"].get("marker"):
            fail("E_CLASSIFICATION", record.get("asset_id"))


@lru_cache(maxsize=1)
def expected_state():
    phase=parse_jsonl(PHASE); targets=sorted((r for r in phase if r.get("product_classification_status")=="candidate_needs_semantic_review" and r.get("artifact_evidence_kind")=="implementation_source" and r.get("source_path","").startswith("src/runtime/")),key=lambda r:r["asset_id"])
    if len(targets)!=59 or {r["source_path"] for r in targets}!=set(PROFILE_PINS): fail("E_TARGET_SET","fixed BASE target/profile set drift")
    disp={r["asset_id"]:r for r in parse_jsonl(DISPOSITION)}; decisions=parse_jsonl(DECISIONS); read_after=parse_jsonl(READ_AFTER)
    ids={r["asset_id"] for r in targets}; paths={r["source_path"] for r in targets}; boundary=boundary_base(); wave_files,wave_edges=wave_data(ids,paths)
    fail_global=static_matches(FAILURE_SOURCE,[]); consumer_global=static_matches(CONSUMER_SOURCE,[])
    rows=[row_expected(r,disp[r["asset_id"]],decisions,read_after,boundary,fail_global,consumer_global,wave_edges) for r in targets]
    input_paths=[PHASE,DISPOSITION,DECISIONS,READ_AFTER,CROSSWALK,DECOMPOSITION,BOUNDARY,APPROVAL_DECISION,APPROVAL_PACKET,*L1.values(),FAILURE_SOURCE,CONSUMER_SOURCE,START,REUSE,MANIFEST,*[x["path"] for x in wave_files],*[ARCHIVE_PREFIX+r["source_path"] for r in targets]]
    expected_input=[{"path":p,"blob":git_blob(p),"bytes":len(git_bytes(p)),"sha256":digest(git_bytes(p))} for p in input_paths]
    counts={c:sum(r["classification"]["category"]==c for r in rows) for c in ["direct_product_basis","multi_product_conflict","insufficient_basis"]}
    return targets,rows,wave_files,wave_edges,expected_input,counts

